import openpyxl
from datetime import datetime, timedelta

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb['Sheet1']

# Define the range to process: C2:C100
start_row = 2
end_row = 100

for row in range(start_row, end_row + 1):
    # Get values from columns A (DATE) and B (STD)
    date_val = ws.cell(row=row, column=1).value
    std_val = ws.cell(row=row, column=2).value

    # Check if both A and B have data
    if date_val is not None and std_val is not None:
        try:
            # Handle date parsing
            # The date might be a string or a datetime object
            if isinstance(date_val, str):
                # Try common date formats
                try:
                    date_obj = datetime.strptime(date_val, '%d-%b-%Y')
                except ValueError:
                    try:
                        date_obj = datetime.strptime(date_val, '%Y-%m-%d')
                    except ValueError:
                        date_obj = None
            elif isinstance(date_val, datetime):
                date_obj = date_val
            else:
                date_obj = None

            # Handle time parsing
            if isinstance(std_val, str):
                try:
                    time_obj = datetime.strptime(std_val, '%H:%M').time()
                except ValueError:
                    try:
                        time_obj = datetime.strptime(std_val, '%H:%M:%S').time()
                    except ValueError:
                        time_obj = None
            elif isinstance(std_val, datetime):
                time_obj = std_val.time()
            elif isinstance(std_val, timedelta):
                # Excel sometimes stores times as timedelta
                total_seconds = int(std_val.total_seconds())
                hours = total_seconds // 3600
                minutes = (total_seconds % 3600) // 60
                seconds = total_seconds % 60
                time_obj = datetime(1, 1, 1, hours, minutes, seconds).time()
            else:
                time_obj = None

            if date_obj is not None and time_obj is not None:
                # Combine date and time
                std_datetime = datetime.combine(date_obj.date(), time_obj)

                # Subtract 30 minutes
                cut_off_datetime = std_datetime - timedelta(minutes=30)

                # Write the result as a datetime object
                ws.cell(row=row, column=3).value = cut_off_datetime
            else:
                # If parsing fails, leave blank or handle error
                ws.cell(row=row, column=3).value = None
        except Exception:
            # If any error occurs, leave blank
            ws.cell(row=row, column=3).value = None
    else:
        # If either A or B is empty, set C to blank
        ws.cell(row=row, column=3).value = None

# Save the workbook
wb.save('output.xlsx')
